        private static readonly Dictionary<string, PatchInfo> Lookup = new(All.Length, StringComparer.Ordinal);
        static Patches()
        {
            foreach (var p in All)
            {
                string key = $"{p.Environment}\0{p.Branch}\0{p.Version}";
                if (!Lookup.ContainsKey(key))
                    Lookup.Add(key, p);
            }
        }

        public static bool TryGet(string environment, string branch, string version, out PatchInfo patch)
            => Lookup.TryGetValue($"{environment}\0{branch}\0{version}", out patch);
    }
